// file_manager.dart - 로컬 .fl 파일 관리

import 'dart:io';
import 'package:path_provider/path_provider.dart';

class FileInfo {
  final String name;
  final String path;
  final DateTime modified;
  final int size;

  FileInfo({
    required this.name,
    required this.path,
    required this.modified,
    required this.size,
  });
}

class FileManager {
  late Directory _codeDirectory;
  static const String _codeFolder = 'freelang_code';

  Future<void> initialize() async {
    final documents = await getApplicationDocumentsDirectory();
    _codeDirectory = Directory('${documents.path}/$_codeFolder');
    if (!_codeDirectory.existsSync()) {
      _codeDirectory.createSync(recursive: true);
    }
  }

  /// 파일 목록 가져오기
  Future<List<FileInfo>> listFiles() async {
    final files = _codeDirectory.listSync();
    return files
        .whereType<File>()
        .where((f) => f.path.endsWith('.fl'))
        .map((f) {
          final stat = f.statSync();
          return FileInfo(
            name: f.path.split('/').last,
            path: f.path,
            modified: stat.modified,
            size: stat.size,
          );
        })
        .toList()
        ..sort((a, b) => b.modified.compareTo(a.modified));
  }

  /// 파일 읽기
  Future<String> readFile(String path) async {
    return File(path).readAsString();
  }

  /// 파일 저장
  Future<void> saveFile(String name, String content) async {
    if (!name.endsWith('.fl')) {
      name += '.fl';
    }
    final file = File('${_codeDirectory.path}/$name');
    await file.writeAsString(content);
  }

  /// 파일 삭제
  Future<void> deleteFile(String path) async {
    await File(path).delete();
  }

  /// 파일 이름 변경
  Future<void> renameFile(String oldPath, String newName) async {
    await File(oldPath).rename('${_codeDirectory.path}/$newName');
  }

  /// 디렉토리 경로
  String get codePath => _codeDirectory.path;
}

// code_file.dart - FreeLang 코드 파일 모델

class CodeFile {
  final String name;
  final String content;
  final String? path;
  final DateTime? created;
  final DateTime? modified;

  CodeFile({
    required this.name,
    required this.content,
    this.path,
    this.created,
    this.modified,
  });

  /// 복사본 생성 (일부 필드만 변경)
  CodeFile copyWith({
    String? name,
    String? content,
    String? path,
    DateTime? created,
    DateTime? modified,
  }) {
    return CodeFile(
      name: name ?? this.name,
      content: content ?? this.content,
      path: path ?? this.path,
      created: created ?? this.created,
      modified: modified ?? this.modified,
    );
  }

  /// JSON 직렬화 (저장용)
  Map<String, dynamic> toJson() => {
        'name': name,
        'content': content,
        'path': path,
        'created': created?.toIso8601String(),
        'modified': modified?.toIso8601String(),
      };

  /// JSON 역직렬화
  factory CodeFile.fromJson(Map<String, dynamic> json) => CodeFile(
        name: json['name'] as String,
        content: json['content'] as String,
        path: json['path'] as String?,
        created: json['created'] != null ? DateTime.parse(json['created']) : null,
        modified:
            json['modified'] != null ? DateTime.parse(json['modified']) : null,
      );

  /// 파일 이름에서 확장자 제거
  String get nameWithoutExtension =>
      name.endsWith('.fl') ? name.substring(0, name.length - 3) : name;

  /// 파일이 저장되었는지 확인
  bool get isSaved => path != null;

  @override
  String toString() => 'CodeFile($name, ${content.length} chars)';
}

