// files_screen.dart - 파일 목록 화면 (FileManager UI)
// 기능: 파일 목록 조회, 열기, 이름변경, 삭제

import 'package:flutter/material.dart';
import '../file_manager.dart';
import '../models/code_file.dart';

class FilesScreen extends StatefulWidget {
  final FileManager fileManager;

  const FilesScreen({
    Key? key,
    required this.fileManager,
  }) : super(key: key);

  @override
  State<FilesScreen> createState() => _FilesScreenState();
}

class _FilesScreenState extends State<FilesScreen> {
  late Future<List<FileInfo>> _filesFuture;

  @override
  void initState() {
    super.initState();
    _filesFuture = widget.fileManager.listFiles();
  }

  void _refreshFiles() {
    setState(() {
      _filesFuture = widget.fileManager.listFiles();
    });
  }

  void _openFile(FileInfo file) {
    // 선택된 파일 반환 (CodeFile로 변환)
    final codeFile = CodeFile(
      name: file.name,
      path: file.path,
      content: '', // editor_screen에서 로드
      modified: file.modified,
    );
    Navigator.pop<CodeFile>(context, codeFile);
  }

  void _deleteFile(FileInfo file) {
    showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('파일 삭제'),
        content: Text('${file.name}을(를) 정말 삭제하시겠습니까?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('취소'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('삭제', style: TextStyle(color: Colors.red)),
          ),
        ],
      ),
    ).then((confirmed) async {
      if (confirmed == true) {
        try {
          await widget.fileManager.deleteFile(file.path);
          _refreshFiles();
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('파일이 삭제되었습니다.')),
            );
          }
        } catch (e) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text('삭제 실패: $e')),
            );
          }
        }
      }
    });
  }

  void _renameFile(FileInfo file) {
    final controller = TextEditingController(text: file.name);

    showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('파일 이름 변경'),
        content: TextField(
          controller: controller,
          decoration: const InputDecoration(hintText: '새 파일명'),
          autofocus: true,
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, null),
            child: const Text('취소'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, controller.text),
            child: const Text('변경'),
          ),
        ],
      ),
    ).then((newName) async {
      if (newName != null && newName.isNotEmpty) {
        try {
          await widget.fileManager.renameFile(file.path, newName);
          _refreshFiles();
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('파일명이 변경되었습니다.')),
            );
          }
        } catch (e) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text('변경 실패: $e')),
            );
          }
        }
      }
      controller.dispose();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('파일 열기'),
        backgroundColor: Colors.grey[900],
        elevation: 0,
      ),
      backgroundColor: Colors.grey[900],
      body: FutureBuilder<List<FileInfo>>(
        future: _filesFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return Center(
              child: CircularProgressIndicator(
                color: Colors.teal[300],
              ),
            );
          }

          if (snapshot.hasError) {
            return Center(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text(
                    '오류: ${snapshot.error}',
                    style: const TextStyle(color: Colors.red),
                  ),
                  const SizedBox(height: 16),
                  ElevatedButton(
                    onPressed: _refreshFiles,
                    child: const Text('다시 시도'),
                  ),
                ],
              ),
            );
          }

          final files = snapshot.data ?? [];

          if (files.isEmpty) {
            return Center(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    Icons.folder_open,
                    size: 64,
                    color: Colors.grey[600],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    '저장된 파일이 없습니다.',
                    style: TextStyle(
                      fontSize: 16,
                      color: Colors.grey[500],
                    ),
                  ),
                ],
              ),
            );
          }

          return ListView.separated(
            itemCount: files.length,
            separatorBuilder: (_, __) => Container(
              height: 1,
              color: Colors.grey[800],
            ),
            itemBuilder: (context, index) {
              final file = files[index];
              final fileSizeKB = (file.size / 1024).toStringAsFixed(1);
              final modifiedTime = _formatTime(file.modified);

              return ListTile(
                leading: Icon(
                  Icons.code,
                  color: Colors.teal[400],
                ),
                title: Text(
                  file.name,
                  style: const TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.w500,
                  ),
                ),
                subtitle: Text(
                  '$fileSizeKB KB • $modifiedTime',
                  style: TextStyle(
                    color: Colors.grey[500],
                    fontSize: 12,
                  ),
                ),
                trailing: PopupMenuButton<String>(
                  color: Colors.grey[800],
                  onSelected: (value) {
                    if (value == 'open') {
                      _openFile(file);
                    } else if (value == 'rename') {
                      _renameFile(file);
                    } else if (value == 'delete') {
                      _deleteFile(file);
                    }
                  },
                  itemBuilder: (BuildContext context) => [
                    const PopupMenuItem(
                      value: 'open',
                      child: Row(
                        children: [
                          Icon(Icons.open_in_new, size: 18),
                          SizedBox(width: 8),
                          Text('열기'),
                        ],
                      ),
                    ),
                    const PopupMenuItem(
                      value: 'rename',
                      child: Row(
                        children: [
                          Icon(Icons.edit, size: 18),
                          SizedBox(width: 8),
                          Text('이름변경'),
                        ],
                      ),
                    ),
                    PopupMenuItem(
                      value: 'delete',
                      child: Row(
                        children: [
                          const Icon(Icons.delete, size: 18, color: Colors.red),
                          const SizedBox(width: 8),
                          Text(
                            '삭제',
                            style: TextStyle(color: Colors.red[300]),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                onTap: () => _openFile(file),
              );
            },
          );
        },
      ),
      floatingActionButton: FloatingActionButton(
        backgroundColor: Colors.teal[600],
        onPressed: _refreshFiles,
        child: const Icon(Icons.refresh),
      ),
    );
  }

  String _formatTime(DateTime dateTime) {
    final now = DateTime.now();
    final diff = now.difference(dateTime);

    if (diff.inMinutes < 1) {
      return '방금';
    } else if (diff.inHours < 1) {
      return '${diff.inMinutes}분 전';
    } else if (diff.inDays < 1) {
      return '${diff.inHours}시간 전';
    } else if (diff.inDays < 7) {
      return '${diff.inDays}일 전';
    } else {
      return '${dateTime.year}-${dateTime.month.toString().padLeft(2, '0')}-${dateTime.day.toString().padLeft(2, '0')}';
    }
  }
}

