    // launchUrl(Uri.parse('freelang://run?code=$encoded'));
  }

  void _showErrors() {
    if (_errors.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('✓ 오류가 없습니다')),
      );
      return;
    }

    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('오류 목록'),
        content: SizedBox(
          width: double.maxFinite,
          child: ListView.builder(
            itemCount: _errors.length,
            itemBuilder: (context, index) {
              final error = _errors[index];
              return ListTile(
                leading: Icon(
                  error.severity == 'error'
                      ? Icons.error
                      : Icons.warning,
                  color: error.severity == 'error'
                      ? Colors.red
                      : Colors.orange,
                  size: 20,
                ),
                title: Text(
                  error.message,
                  style: const TextStyle(fontSize: 12),
                ),
                subtitle: Text(
                  '${error.line + 1}:${error.col}',
