class EditorError {
  final int line;
  final int col;
  final String message;
  final String severity; // 'error' or 'warning'

  EditorError({
    required this.line,
    required this.col,
    required this.message,
    required this.severity,
  });

  @override
  String toString() => 'EditorError($line:$col) $message';
}

