// recommendations.go - 추천 시스템 (좋아요 기반)

package api

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
)

// ==================== HTTP 핸들러 ====================

// GET /api/v2/recommendations?limit=10
// 좋아요 순 상위 스니펫 조회 (인증 불필요)
func GetRecommendations(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// limit 파라미터 (기본값: 10, 최대: 100)
		limitStr := r.URL.Query().Get("limit")
		limit := 10
		if limitStr != "" {
			if l, err := strconv.Atoi(limitStr); err == nil && l > 0 && l <= 100 {
				limit = l
			}
		}

		// 좋아요 순 상위 스니펫 조회
		rows, err := db.Query(`
			SELECT id, title, code, author, tags, likes, created_at
			FROM snippets
			ORDER BY likes DESC, created_at DESC
			LIMIT ?
		`, limit)

		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database query failed")
			return
		}
		defer rows.Close()

		snippets := []Snippet{}
		for rows.Next() {
			var s Snippet
			if err := rows.Scan(&s.ID, &s.Title, &s.Code, &s.Author, &s.Tags, &s.Likes, &s.CreatedAt); err != nil {
				continue
			}
			snippets = append(snippets, s)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    snippets,
			"count":   len(snippets),
		})
	}
}

