  String? _error;
  int _currentPage = 1;
  final int _pageSize = 10;
  late TabController _tabController;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    _tabController.addListener(_onTabChanged);
    _loadSnippets();
    _loadRecommendedSnippets();
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  void _onTabChanged() {
    if (_tabController.index == 1 && _recommendedSnippets.isEmpty) {
      _loadRecommendedSnippets();
    }
  }

  Future<void> _loadSnippets() async {
    if (_isLoading) return;

    setState(() {
      _isLoading = true;
      _error = null;
    });

    try {
      await _apiClient.initialize();
      final snippets = await _apiClient.getSnippets(
        page: _currentPage,
        limit: _pageSize,
        tag: _selectedTag,
      );

      setState(() {
        _snippets = snippets;
      });
    } catch (e) {
      setState(() {
        _error = e.toString();
        // 로컬 데이터로 폴백 (네트워크 오류 시)
