    slivers: [
      // 태그 필터
      SliverToBoxAdapter(
        child: SizedBox(
          height: 50,
          child: ListView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            children: [
              FilterChip(
                label: const Text('모두'),
                selected: _selectedTag == null,
                onSelected: (_) => _onTagChanged(null),
              ),
              const SizedBox(width: 8),
              ...['algorithm', 'game', 'utility', 'string', 'array']
                  .map((tag) => Padding(
                        padding: const EdgeInsets.only(right: 8),
                        child: FilterChip(
                          label: Text(tag),
                          selected: _selectedTag == tag,
                          onSelected: (_) => _onTagChanged(tag),
                        ),
                      ))
                  .toList(),
            ],
          ),
        ),
      ),

      // 로딩 상태
      if (_isLoading)
        const SliverToBoxAdapter(
          child: SizedBox(
            height: 100,
            child: Center(
              child: CircularProgressIndicator(),
            ),
          ),
        ),

      // 에러 메시지
      if (_error != null && !_isLoading)
        SliverToBoxAdapter(
          child: Container(
            padding: const EdgeInsets.all(12),
            color: Colors.orange[100],
            child: Row(
              children: [
                Icon(Icons.warning, color: Colors.orange[900]),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    '서버 연결 실패: 로컬 데이터 표시 중',
                    style: TextStyle(color: Colors.orange[900]),
                  ),
                ),
              ],
            ),
          ),
        ),

      // 스니펫 목록
      if (filtered.isEmpty && !_isLoading)
        const SliverToBoxAdapter(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Center(
              child: Text('스니펫이 없습니다'),
            ),
          ),
        ),

      SliverList(
        delegate: SliverChildBuilderDelegate(
          (context, index) {
            final snippet = filtered[index];
            return SnippetCard(
              snippet: snippet,
              onLikeTapped: () async {
                // TODO: 좋아요 API 호출
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('좋아요했습니다!')),
                );
              },
            );
          },
          childCount: filtered.length,
        ),
      ),
    ],
  );
}

Widget _buildPopularTab() {
  if (_isLoadingRecommended) {
    return const Center(
      child: CircularProgressIndicator(),
    );
  }

  if (_recommendedSnippets.isEmpty) {
    return const Center(
      child: Text('인기 스니펫이 없습니다'),
    );
  }

  return CustomScrollView(
    slivers: [
      SliverList(
        delegate: SliverChildBuilderDelegate(
          (context, index) {
            final snippet = _recommendedSnippets[index];
            return SnippetCard(
              snippet: snippet,
              onLikeTapped: () async {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('좋아요했습니다!')),
                );
              },
            );
          },
          childCount: _recommendedSnippets.length,
        ),
      ),
    ],
  );
}

