// feed_screen.dart - 코드 스니펫 피드 (REST API 연동)

import 'package:flutter/material.dart';
import '../services/hub_api_client.dart';

class FeedScreen extends StatefulWidget {
  const FeedScreen({Key? key}) : super(key: key);

  @override
  State<FeedScreen> createState() => _FeedScreenState();
}

class _FeedScreenState extends State<FeedScreen>
    with SingleTickerProviderStateMixin {
  final HubApiClient _apiClient = HubApiClient();

  List<SnippetResponse> _snippets = [];
  List<SnippetResponse> _recommendedSnippets = [];
  String? _selectedTag;
  bool _isLoading = false;
  bool _isLoadingRecommended = false;
  String? _error;
  int _currentPage = 1;
  final int _pageSize = 10;
  late TabController _tabController;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    _tabController.addListener(_onTabChanged);
    _loadSnippets();
    _loadRecommendedSnippets();
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  void _onTabChanged() {
    if (_tabController.index == 1 && _recommendedSnippets.isEmpty) {
      _loadRecommendedSnippets();
    }
  }

  Future<void> _loadSnippets() async {
    if (_isLoading) return;

    setState(() {
      _isLoading = true;
      _error = null;
    });

    try {
      await _apiClient.initialize();
      final snippets = await _apiClient.getSnippets(
        page: _currentPage,
        limit: _pageSize,
        tag: _selectedTag,
      );

      setState(() {
        _snippets = snippets;
      });
    } catch (e) {
      setState(() {
        _error = e.toString();
        // 로컬 데이터로 폴백 (네트워크 오류 시)
        _snippets = _getLocalSnippets();
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  Future<void> _loadRecommendedSnippets() async {
    if (_isLoadingRecommended) return;

    setState(() {
      _isLoadingRecommended = true;
    });

    try {
      await _apiClient.initialize();
      final snippets = await _apiClient.getRecommendations(limit: 20);

      setState(() {
        _recommendedSnippets = snippets;
      });
    } catch (e) {
      print('추천 로드 실패: $e');
      setState(() {
        _recommendedSnippets = _getLocalSnippets();
      });
    } finally {
      setState(() {
        _isLoadingRecommended = false;
      });
    }
  }

  // 네트워크 오류 시 로컬 샘플 데이터
  List<SnippetResponse> _getLocalSnippets() {
    return [
      SnippetResponse(
        id: '1',
        title: '피보나치 수열',
        code: 'let fib(n) { if n <= 1 { n } else { fib(n-1) + fib(n-2) } }',
        author: 'alice',
        tags: ['algorithm', 'recursion'],
        likes: 42,
        createdAt: '2 시간 전',
      ),
      SnippetResponse(
        id: '2',
        title: '배열 정렬',
        code: 'let sort(arr) { /* bubble sort */ }',
        author: 'bob',
        tags: ['sorting', 'array'],
        likes: 28,
        createdAt: '5 시간 전',
      ),
      SnippetResponse(
        id: '3',
        title: '문자열 역순',
        code: 'let reverse(s) { s.chars().reverse().join() }',
        author: 'charlie',
        tags: ['string', 'utility'],
        likes: 15,
        createdAt: '1 일 전',
      ),
    ];
  }

  void _onTagChanged(String? tag) {
    setState(() {
      _selectedTag = tag;
      _currentPage = 1;
    });
    _loadSnippets();
  }

  @override
  Widget build(BuildContext context) {
    final filtered = _snippets
        .where((s) => _selectedTag == null || s.tags.contains(_selectedTag))
        .toList();

    return CustomScrollView(
      slivers: [
        // 태그 필터
        SliverToBoxAdapter(
          child: SizedBox(
            height: 50,
            child: ListView(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 12),
              children: [
                FilterChip(
                  label: const Text('모두'),
                  selected: _selectedTag == null,
                  onSelected: (_) => _onTagChanged(null),
                ),
                const SizedBox(width: 8),
                ...['algorithm', 'game', 'utility', 'string', 'array']
                    .map((tag) => Padding(
                          padding: const EdgeInsets.only(right: 8),
                          child: FilterChip(
                            label: Text(tag),
                            selected: _selectedTag == tag,
                            onSelected: (_) => _onTagChanged(tag),
                          ),
                        ))
                    .toList(),
              ],
            ),
          ),
        ),

        // 로딩 상태
        if (_isLoading)
          const SliverToBoxAdapter(
            child: SizedBox(
              height: 100,
              child: Center(
                child: CircularProgressIndicator(),
              ),
            ),
          ),

        // 에러 메시지
        if (_error != null && !_isLoading)
          SliverToBoxAdapter(
            child: Container(
              padding: const EdgeInsets.all(12),
              color: Colors.orange[100],
              child: Row(
                children: [
                  Icon(Icons.warning, color: Colors.orange[900]),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      '서버 연결 실패: 로컬 데이터 표시 중',
                      style: TextStyle(color: Colors.orange[900]),
                    ),
                  ),
                ],
              ),
            ),
          ),

        // 스니펫 목록
        if (filtered.isEmpty && !_isLoading)
          const SliverToBoxAdapter(
            child: Padding(
              padding: EdgeInsets.all(24),
              child: Center(
                child: Text('스니펫이 없습니다'),
              ),
            ),
          ),

        SliverList(
          delegate: SliverChildBuilderDelegate(
            (context, index) {
              final snippet = filtered[index];
              return SnippetCard(
                snippet: snippet,
                onLikeTapped: () async {
                  // TODO: 좋아요 API 호출
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(content: Text('좋아요했습니다!')),
                  );
                },
              );
            },
            childCount: filtered.length,
          ),
        ),
      ],
    );
  }
}

class SnippetCard extends StatefulWidget {
  final SnippetResponse snippet;
  final VoidCallback? onLikeTapped;

  const SnippetCard({
    Key? key,
    required this.snippet,
    this.onLikeTapped,
  }) : super(key: key);

  @override
  State<SnippetCard> createState() => _SnippetCardState();
}

class _SnippetCardState extends State<SnippetCard> {
  late int _likes;
  late bool _isLiked;

  @override
  void initState() {
    super.initState();
    _likes = widget.snippet.likes;
    _isLiked = false;
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
      child: InkWell(
        onTap: () {
          // 스니펫 상세 보기
        },
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // 제목
              Text(
                widget.snippet.title,
                style: const TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 8),

              // 코드 미리보기
              Container(
                padding: const EdgeInsets.all(8),
                color: Colors.grey[900],
                child: Text(
                  widget.snippet.code,
                  style: TextStyle(
                    fontFamily: 'Monaco',
                    fontSize: 11,
                    color: Colors.grey[300],
                  ),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(height: 8),

              // 태그
              Wrap(
                spacing: 4,
                children: widget.snippet.tags
                    .map((tag) => Chip(
                          label: Text(
                            tag,
                            style: const TextStyle(fontSize: 11),
                          ),
                          visualDensity: VisualDensity.compact,
                        ))
                    .toList(),
              ),
              const SizedBox(height: 8),

              // 작성자, 날짜, 좋아요
              Row(
                children: [
                  CircleAvatar(
                    radius: 16,
                    backgroundColor: Colors.teal[300],
                    child: Text(
                      widget.snippet.author[0].toUpperCase(),
                      style: const TextStyle(
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        widget.snippet.author,
                        style: const TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      Text(
                        widget.snippet.createdAt,
                        style: TextStyle(
                          fontSize: 10,
                          color: Colors.grey[600],
                        ),
                      ),
                    ],
                  ),
                  const Spacer(),
                  IconButton(
                    icon: Icon(
                      _isLiked ? Icons.favorite : Icons.favorite_border,
                      color: _isLiked ? Colors.red : null,
                    ),
                    onPressed: () {
                      setState(() {
                        _isLiked = !_isLiked;
                        _likes += _isLiked ? 1 : -1;
                      });
                      widget.onLikeTapped?.call();
                    },
                  ),
                  Text('$_likes'),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

