// notifications.go - 알림 시스템

package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strconv"
	"time"
)

// ==================== 데이터 모델 ====================

type Notification struct {
	ID            string    `json:"id"`
	UserID        string    `json:"user_id"`
	Type          string    `json:"type"` // 'comment' | 'like'
	ActorUsername string    `json:"actor_username"`
	SnippetID     string    `json:"snippet_id"`
	SnippetTitle  string    `json:"snippet_title"`
	IsRead        bool      `json:"is_read"`
	CreatedAt     time.Time `json:"created_at"`
}

// ==================== 테이블 초기화 ====================

func InitNotificationsTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS notifications (
		id TEXT PRIMARY KEY,
		user_id TEXT NOT NULL,
		type TEXT NOT NULL,
		actor_username TEXT NOT NULL,
		snippet_id TEXT NOT NULL,
		snippet_title TEXT NOT NULL,
		is_read INTEGER DEFAULT 0,
		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
		FOREIGN KEY (user_id) REFERENCES users(id),
		FOREIGN KEY (snippet_id) REFERENCES snippets(id) ON DELETE CASCADE
	);

	CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);
	`

	_, err := db.Exec(schema)
	return err
}

// ==================== HTTP 핸들러 ====================

// GET /api/v2/notifications
// JWT 필요, 내 알림 목록 (최신 30개)
func GetNotifications(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		rows, err := db.Query(`
			SELECT id, user_id, type, actor_username, snippet_id, snippet_title, is_read, created_at
			FROM notifications
			WHERE user_id = ?
			ORDER BY created_at DESC
			LIMIT 30
		`, userID)

		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database query failed", 500)
			return
		}
		defer rows.Close()

		notifications := []Notification{}
		for rows.Next() {
			var n Notification
			var isRead int
			if err := rows.Scan(&n.ID, &n.UserID, &n.Type, &n.ActorUsername, &n.SnippetID, &n.SnippetTitle, &isRead, &n.CreatedAt); err != nil {
				continue
			}
			n.IsRead = isRead == 1
			notifications = append(notifications, n)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    notifications,
			"count":   len(notifications),
		})
	}
}

// POST /api/v2/notifications/{id}/read
// JWT 필요, 알림을 읽음 처리
func MarkNotificationRead(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		notificationID := r.PathValue("id")
		if notificationID == "" {
			WriteError(w, http.StatusBadRequest, "Notification ID required", 400)
			return
		}

		// 자신의 알림인지 확인
		var ownerID string
